// "Check signature": accept only calls from the Werkstudent Radar pipeline.
// radar/notify.py sends X-Radar-Signature: sha256=HMAC-SHA256(secret, "<timestamp>." + body)
// and X-Radar-Timestamp; this node recomputes it over the raw body bytes. It also drops the
// postings already sent that day, so a repeated daily run posts only the ones it found later
// and a day with nothing left is skipped; test payloads always pass.
//
// The secret: self-hosted, WEBHOOK_SECRET in the environment (.env next to docker-compose.yml).
// n8n Cloud has no environment variables: paste it into SECRET below instead.
const SECRET = '';
const MAX_AGE_S = 600;   // a call older than 10 minutes is a replay

const crypto = require('crypto');
let secret = SECRET;
if (!secret) {
  try { secret = $env.WEBHOOK_SECRET || ''; } catch (e) { secret = ''; }
}
const reject = (status, reason) => [{ json: { ok: false, status, reason } }];
if (!secret) return reject(500, 'WEBHOOK_SECRET is not set in n8n');

const item = $input.first();
const headers = item.json.headers || {};
const ts = String(headers['x-radar-timestamp'] || '');
const given = String(headers['x-radar-signature'] || '');
if (!/^\d{1,12}$/.test(ts) || Math.abs(Date.now() / 1000 - Number(ts)) > MAX_AGE_S) {
  return reject(401, 'missing or expired timestamp');
}

// The exact bytes that were signed (Webhook node option "Raw Body"); parsed JSON would differ.
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
const a = Buffer.from(given);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject(401, 'bad signature');

let payload;
try {
  payload = JSON.parse(raw.toString('utf8'));
} catch (e) {
  return reject(400, 'body is not JSON');
}
if (payload.event !== 'new_postings' || !Array.isArray(payload.jobs)) return reject(400, 'unknown event');

// "Build messages" stores the day it sent last and the ids of that day's postings.
const sent = $getWorkflowStaticData('global');
if (!payload.test && sent.lastAsOf === payload.as_of) {
  // Stored before the ids were (only lastAsOf): the whole day counts as sent.
  const ids = new Set(Array.isArray(sent.sentIds) ? sent.sentIds : payload.jobs.map((j) => j.id));
  const jobs = payload.jobs.filter((j) => !ids.has(j.id));
  if (!jobs.length) return [{ json: { ok: false, status: 200, reason: `${payload.as_of} was already sent` } }];
  const total = payload.total - (payload.jobs.length - jobs.length);
  return [{ json: { ok: true, status: 200, payload: { ...payload, jobs, total, more: true } } }];
}
return [{ json: { ok: true, status: 200, payload } }];

// "Build messages": one Telegram message per target with the new jobs that pass its filter,
// then marks the day and its postings as sent ("Check signature" drops them if the daily run
// is repeated; `more` marks a payload with only the postings found since).
// Edit the targets here after importing. Empty lists mean "no filter".
//   chatId         "@channel_name" for a public channel, or the numeric chat ID (see README)
//   cities         as on the site: "Berlin", "München", "Hamburg", …
//   includeRemote  also jobs that are remote anywhere in Germany (no city)
//   fields         field ids: it, data, engineering, marketing, sales, finance, consulting,
//                  product, design, hr, ops, research, admin, legal, education, health, retail, other
//   skills         skill names as on the site ("Python", "SQL", "Excel", …); a job needs one of them
//   noGerman       only jobs that don't require German
const TARGETS = [
  { target: 'channel', chatId: '@your_channel', cities: ['Berlin'], includeRemote: false, fields: [], skills: [], noGerman: false },
  { target: 'me', chatId: '123456789', cities: ['Berlin'], includeRemote: true, fields: ['it', 'data'], skills: [], noGerman: false },
];
const MAX_JOBS = 10;     // per message; the rest is "+N more" with a link to the site

const p = $input.first().json.payload;
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const lower = (list) => (list || []).map((s) => String(s).toLowerCase());
const [y, m, d] = String(p.as_of).split('-').map(Number);
const day = `${d} ${MONTHS[m - 1]} ${y}`;

function matches(job, t) {
  const cities = t.cities || [];
  if (cities.length && !(cities.includes(job.city) || (t.includeRemote && job.city === ''))) return false;
  if ((t.fields || []).length && !t.fields.includes(job.field)) return false;
  const skills = lower(t.skills);
  if (skills.length && !lower(job.skills).some((s) => skills.includes(s))) return false;
  if (t.noGerman && !job.no_german) return false;
  return true;
}

// The site with the target's filter, where the rest of the jobs can be found.
// (No URLSearchParams: n8n's Code node sandbox doesn't have it.)
function siteLink(t) {
  const q = [];
  if ((t.fields || []).length === 1) q.push(['field', t.fields[0]]);
  if ((t.cities || []).length === 1) q.push(['city', t.cities[0]]);
  if (t.noGerman) q.push(['german', 'no']);
  const s = q.map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
  return p.site + (s ? `?${s}` : '');
}

function line(job) {
  const pay = typeof job.pay === 'number' ? `€${job.pay.toFixed(2)}/h` : null;
  const where = job.city || 'Remote (DE)';
  const facts = [cut(job.company || '', 60), where, pay, job.field_label].filter(Boolean).map(esc).join(' · ');
  return `• <a href="${esc(job.url)}">${esc(cut(job.title || '', 120))}</a>\n   ${facts}`;
}

const out = [];
for (const t of TARGETS) {
  const jobs = p.jobs.filter((j) => matches(j, t))
    .sort((a, b) => (b.pay ?? -1) - (a.pay ?? -1) || String(a.title).localeCompare(String(b.title)));
  if (!jobs.length) continue;
  const where = (t.cities || []).length ? t.cities.join(', ') : 'Germany';
  const head = `${p.test ? '🧪 Test · ' : ''}<b>${jobs.length} ${p.more ? 'more ' : ''}new Werkstudent job${jobs.length === 1 ? '' : 's'} · ${esc(where)}</b>\n${day}`;
  const shown = jobs.slice(0, MAX_JOBS).map(line);
  const more = jobs.length - shown.length;
  const tail = more > 0
    ? `<a href="${esc(siteLink(t))}">+${more} more on Werkstudent Radar</a>`
    : `<a href="${esc(siteLink(t))}">Werkstudent Radar</a>`;
  out.push({ json: { target: t.target, chatId: t.chatId, count: jobs.length, text: [head, shown.join('\n'), tail].join('\n\n') } });
}
// Remember the day only now, so a day whose messages couldn't be built isn't skipped later.
// All of the payload's ids count as sent, also those no target wanted: they won't match later either.
if (!p.test) {
  const state = $getWorkflowStaticData('global');
  const before = state.lastAsOf === p.as_of && Array.isArray(state.sentIds) ? state.sentIds : [];
  state.lastAsOf = p.as_of;
  state.sentIds = before.concat(p.jobs.map((j) => j.id));
}
return out;
